class NVTimesheetUpdateBatch extends RunBaseBatch implements BatchRetryable
{
    HcmWorkerRecId  worker;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        worker
    #endmacro

}

Method.Source:
public HcmWorkerRecId parmWorker(HcmWorkerRecId _worker = worker)
{
    worker = _worker;
    return worker;
}

public Object dialog()
{
    DialogRunbase       dialog = super();

    return dialog;
}

public void run()
{
    #OCCRetryCount

    try
    {
        NVTimesheetChangeHandler timesheetChangeHandler;

        while select timesheetChangeHandler
        {
            ttsbegin;
            if(timesheetChangeHandler.RefTableId == tableNum(LeaveRequest))
            {
                LeaveRequest leaveRequest = LeaveRequest::find(timesheetChangeHandler.RefRecId);
                if(leaveRequest)
                {
                    NVTimesheetUpdateHandler::updateLeaveRequestTimesheet(leaveRequest.RecId);
                }
            }
            else if(timesheetChangeHandler.RefTableId == tableNum(NVTrvWorkerExpenseRequest))
            {
                NVTrvWorkerExpenseRequest trvExpenseRequest = NVTrvWorkerExpenseRequest::find(timesheetChangeHandler.RefRecId);
                if(trvExpenseRequest)
                {
                    NVTimesheetUpdateHandler::updateTrvExpenseRequestTimesheet(trvExpenseRequest.RecId);
                }
            }
            timesheetChangeHandler.selectForUpdate(true);
            timesheetChangeHandler.delete();
            ttscommit;
        }

        info("Operation completed.");
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (!(xSession::currentRetryCount() >= #RetryNum))
            {
                retry;
            }
        }
    }
}

public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);
    ;
    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

public boolean validate(Object _calledFrom = null)
{
    if (false)
        return checkFailed("");

    return true;
}

static NVTimesheetUpdateBatch construct()
{
    return new NVTimesheetUpdateBatch();
}

static void main(Args args)
{
    NVTimesheetUpdateBatch update = NVTimesheetUpdateBatch::construct();

    if(args.record() as NvTimeSheetHeader)
    {
        update.runOperation();
    }

    else if (update.prompt())
        update.runOperation();
}

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
